//! Parity and regression tests for the Voxtral TTS family.
//!
//! Pinned fixtures reside in `testdata/tts_voxtral_tts/`, generated by
//! `tools/gen_voxtral_tts_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference modules (the tekken speech
//! tokenizer replaced by canned prompt ids, the voice table loaded
//! through the reference `_get_voice_embedding`), saves the checkpoint
//! under the raw consolidated Mistral tensor names, records every
//! `mx.random.normal` draw, and verifies the recording run against a
//! fresh `model.generate` and a second replay on the Python side.

use std::collections::VecDeque;
use std::path::{Path, PathBuf};

use serde_json::Value;

use super::{FlowNoise, GenerateParams, Model, SeededFlowNoise};
use crate::SpeechError;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_voxtral_tts")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum differences when the gates were frozen; assertions
/// use these values, not re-measured ones. The prompt embeddings and
/// codes are exact by construction (lookups plus copies, and the codes
/// are integers), the LM hidden states hold the usual dense-transformer
/// f32 noise, and the codec waveform adds the ALiBi softmax exp noise
/// through four attention stages.
const EMBEDS_TOLERANCE: f32 = 1e-6;
const HIDDEN_TOLERANCE: f32 = 2e-5;
const WAVEFORM_TOLERANCE: f32 = 2e-5;
const STAGE_TOLERANCE: f32 = 2e-5;

/// The recorded `mx.random.normal` draws replayed in reference order.
pub(crate) struct ReplayNoise {
    draws: VecDeque<(Vec<usize>, Vec<f32>)>,
}

impl ReplayNoise {
    pub(crate) fn from_trace(traces: &Value) -> Self {
        let draws: Vec<(Vec<usize>, Vec<f32>)> = traces["noise_draws"]
            .as_array()
            .expect("draws")
            .iter()
            .map(|draw| {
                (
                    draw["shape"]
                        .as_array()
                        .expect("shape")
                        .iter()
                        .map(|v| v.as_u64().expect("dim") as usize)
                        .collect::<Vec<_>>(),
                    f32_vec(&draw["values"]),
                )
            })
            .collect();
        Self {
            draws: VecDeque::from(draws),
        }
    }
}

impl FlowNoise for ReplayNoise {
    fn normal(&mut self, n: usize) -> Vec<f32> {
        let (recorded, values) = self
            .draws
            .pop_front()
            .expect("the fixture ran out of recorded draws");
        assert_eq!(
            recorded,
            vec![1, n],
            "recorded draw shape does not match the request"
        );
        values
    }
}

#[test]
fn generate_case_replays_the_reference_run() {
    let traces = read_json(&testdata("generate/traces.json"));
    let mut model = Model::open(&testdata("generate")).expect("family model loads");
    let prompt_ids = i32_vec(&traces["prompt"]["ids"]);

    // Prompt embeddings: the text table rows with the [AUDIO] positions
    // replaced by the voice rows.
    let voice = model.voice("casual_male").expect("voice loads");
    let embeddings = model
        .build_prompt_embeddings(&prompt_ids, Some(&voice))
        .expect("prompt embeddings");
    let diff = max_abs_diff(&embeddings, &f32_vec(&traces["prompt"]["input_embeddings"]));
    assert!(diff <= EMBEDS_TOLERANCE, "input embeddings diff {diff}");

    let mut noise = ReplayNoise::from_trace(&traces);
    let generated = model
        .generate(
            &prompt_ids,
            Some("casual_male"),
            &GenerateParams {
                max_tokens: traces["generate"]["max_tokens"].as_u64().unwrap() as usize,
            },
            &mut noise,
        )
        .expect("generate");
    assert!(noise.draws.is_empty(), "draws left unconsumed");

    // The end token fired at step 3, so the recorded steps carry three
    // running frames plus the stop check.
    let steps = traces["steps"].as_array().expect("steps");
    assert_eq!(steps.len(), 4);
    assert!(traces["stopped"].as_bool().unwrap());
    assert!(generated.stopped);
    assert_eq!(generated.frames, 3);
    assert_eq!(generated.codes, i32_vec(&traces["codes"]));

    // Per-step LM hidden states feed the acoustic head, so they are the
    // stage gate for the whole loop.
    let dim = model.config.dim;
    for (step, want) in generated_hidden(
        &mut model,
        &prompt_ids,
        &traces,
        &mut ReplayNoise::from_trace(&traces),
    )
    .iter()
    .zip(steps)
    {
        let diff = max_abs_diff(step, &f32_vec(&want["hidden"]));
        assert!(diff <= HIDDEN_TOLERANCE, "hidden diff {diff}");
    }
    let _ = dim;

    let diff = max_abs_diff(&generated.samples, &f32_vec(&traces["waveform"]));
    assert!(diff <= WAVEFORM_TOLERANCE, "waveform diff {diff}");
    assert_eq!(
        generated.sample_rate,
        traces["sample_rate"].as_u64().unwrap() as u32
    );
    assert_eq!(
        generated.samples.len(),
        traces["waveform"].as_array().unwrap().len()
    );
}

/// Re-runs the reference loop stage by stage, returning the hidden state
/// before each step (the recorded per-step gate).
fn generated_hidden(
    model: &mut Model,
    prompt_ids: &[i32],
    traces: &Value,
    noise: &mut dyn FlowNoise,
) -> Vec<Vec<f32>> {
    use crate::lm::engine::Input;
    let dim = model.config.dim;
    let voice = model.voice("casual_male").unwrap();
    let embeddings = model
        .build_prompt_embeddings(prompt_ids, Some(&voice))
        .expect("prompt embeddings");
    for cache in model.caches.iter_mut() {
        cache.reset();
    }
    let mut hidden = model
        .language_model
        .forward_hidden(Input::Embeddings(&embeddings), Some(&mut model.caches))
        .expect("prefill");
    let uncond = vec![0.0f32; dim];
    let mut hiddens = Vec::new();
    for step in traces["steps"].as_array().expect("steps").iter() {
        let h = hidden[hidden.len() - dim..].to_vec();
        hiddens.push(h.clone());
        let codes = model
            .acoustic
            .decode_one_frame(&h, &uncond, noise)
            .expect("frame");
        if step["semantic"].as_i64().unwrap() <= 1 {
            break;
        }
        // Sum the per-codebook embedding rows into the next LM input.
        let mut next = vec![0.0f32; dim];
        for (codebook, &code) in codes.iter().enumerate() {
            let offset = match codebook {
                0 => 0,
                _ => {
                    model.config.semantic_codebook_size
                        + 2
                        + (codebook - 1) * (model.config.acoustic_codebook_size + 2)
                }
            };
            let row = &model.audio_embeddings
                [((offset + code as usize) * dim)..((offset + code as usize + 1) * dim)];
            for (value, add) in next.iter_mut().zip(row) {
                *value += *add;
            }
        }
        hidden = model
            .language_model
            .forward_hidden(Input::Embeddings(&next), Some(&mut model.caches))
            .expect("step");
    }
    hiddens
}

#[test]
fn flow_stage_math_matches_the_reference() {
    let traces = read_json(&testdata("generate/traces.json"));
    let model = Model::open(&testdata("generate")).expect("family model loads");
    let flow = &traces["flow_stage"];
    let h = f32_vec(&traces["steps"][0]["hidden"]);
    let uncond = vec![0.0f32; model.config.dim];
    let mut noise = ReplayNoise::from_trace(&traces);

    // Mirror the reference Euler loop with its internals exposed.
    let head = &model.acoustic;
    let n = model.config.n_acoustic_codebook;
    let steps = 8usize;
    let mut x_t: Vec<f32> = noise
        .normal(n)
        .into_iter()
        .map(|v| v * model.config.acoustic_sigma_max)
        .collect();
    for (index, want) in flow["steps"]
        .as_array()
        .expect("flow steps")
        .iter()
        .enumerate()
    {
        let t = index as f32 / (steps - 1) as f32;
        let dt = (index + 1) as f32 / (steps - 1) as f32 - t;
        assert!((want["t"].as_f64().unwrap() as f32 - t).abs() < 1e-6);
        let v_cond = head.predict_velocity(&x_t, t, &h).expect("velocity");
        let v_uncond = head.predict_velocity(&x_t, t, &uncond).expect("velocity");
        let diff = max_abs_diff(&v_cond, &f32_vec(&want["v_cond"]));
        assert!(diff <= HIDDEN_TOLERANCE, "v_cond[{index}] diff {diff}");
        let diff = max_abs_diff(&v_uncond, &f32_vec(&want["v_uncond"]));
        assert!(diff <= HIDDEN_TOLERANCE, "v_uncond[{index}] diff {diff}");
        for (value, (cond, unc)) in x_t.iter_mut().zip(v_cond.iter().zip(&v_uncond)) {
            *value += (1.2 * cond + (1.0 - 1.2) * unc) * dt;
        }
        let diff = max_abs_diff(&x_t, &f32_vec(&want["x_t"]));
        assert!(diff <= HIDDEN_TOLERANCE, "x_t[{index}] diff {diff}");
    }
    let diff = max_abs_diff(&x_t, &f32_vec(&flow["x_t_final"]));
    assert!(diff <= HIDDEN_TOLERANCE, "x_t final diff {diff}");

    // Quantize the final state exactly like the reference decode: the
    // frame equals the loop's first frame.
    let mut codes = Vec::new();
    codes.push(head.predict_semantic(&h) as i32);
    let size = model.config.acoustic_codebook_size as f32;
    for value in &x_t {
        let clamped = value.clamp(-1.0, 1.0);
        let scaled = super::round_ties_even((clamped + 1.0) * (size - 1.0) / 2.0);
        let quantized = scaled.clamp(0.0, size - 1.0);
        codes.push(quantized as i32 + 2);
    }
    assert_eq!(codes, i32_vec(&flow["codes"]));
}

#[test]
fn length_case_runs_to_max_tokens() {
    let traces = read_json(&testdata("length/traces.json"));
    let mut model = Model::open(&testdata("length")).expect("family model loads");
    let prompt_ids = i32_vec(&traces["prompt"]["ids"]);
    let mut noise = ReplayNoise::from_trace(&traces);
    let generated = model
        .generate(
            &prompt_ids,
            Some("casual_male"),
            &GenerateParams {
                max_tokens: traces["generate"]["max_tokens"].as_u64().unwrap() as usize,
            },
            &mut noise,
        )
        .expect("generate");
    assert!(noise.draws.is_empty(), "draws left unconsumed");
    assert!(!generated.stopped);
    assert_eq!(generated.frames, 5);
    assert_eq!(generated.codes, i32_vec(&traces["codes"]));
    let diff = max_abs_diff(&generated.samples, &f32_vec(&traces["waveform"]));
    assert!(diff <= WAVEFORM_TOLERANCE, "waveform diff {diff}");
}

#[test]
fn codec_case_decodes_the_grid_stage_by_stage() {
    let traces = read_json(&testdata("codec/traces.json"));
    let model = Model::open(&testdata("codec")).expect("family model loads");
    let codes = i32_vec(&traces["codes"]);
    let frames = traces["frames"].as_u64().unwrap() as usize;
    let (samples, stages) = model.decode_codes_traced(&codes, frames).expect("decode");

    let recorded = traces["stages"].as_array().expect("stages");
    assert_eq!(stages.len(), recorded.len());
    for ((stage, values, rows, width), want) in stages.iter().zip(recorded) {
        assert_eq!(*stage, want["stage"].as_str().unwrap());
        assert_eq!(*rows, want["rows"].as_u64().unwrap() as usize);
        assert_eq!(*width, want["width"].as_u64().unwrap() as usize);
        let diff = max_abs_diff(values, &f32_vec(&want["values"]));
        assert!(
            diff <= STAGE_TOLERANCE,
            "stage {stage} (rows {rows}) diff {diff}"
        );
    }
    let diff = max_abs_diff(&samples, &f32_vec(&traces["waveform"]));
    assert!(diff <= WAVEFORM_TOLERANCE, "waveform diff {diff}");
}

#[test]
fn seeded_threefry_reproduces_the_recorded_normal_draws() {
    // The crate-local threefry matches the reference draw stream to
    // well under the loop gates (voxcpm pins the same 1e-6), so
    // standalone seeded runs need no replay.
    for name in ["generate", "length"] {
        let traces = read_json(&testdata(format!("{name}/traces.json").as_str()));
        let seed = traces["draw_seed"].as_u64().unwrap();
        let mut noise = SeededFlowNoise::new(seed);
        for draw in traces["noise_draws"].as_array().expect("draws") {
            let values = f32_vec(&draw["values"]);
            let produced = noise.normal(values.len());
            let diff = max_abs_diff(&produced, &values);
            assert!(diff < 1e-6, "{name}: seeded draw diff {diff:e}");
        }
    }
}

#[test]
fn config_parses_both_layouts() {
    let fixture = read_json(&testdata("generate/config.json"));
    let config = super::ModelConfig::from_json(&fixture).expect("direct format");
    assert_eq!(config.model_type, "voxtral_tts");
    assert_eq!(config.dim, 32);
    assert_eq!(config.n_layers, 2);
    assert_eq!(config.semantic_codebook_size, 32);
    assert_eq!(config.n_acoustic_codebook, 6);
    assert_eq!(config.audio_token_id, 24);
    assert_eq!(config.begin_audio_token_id, 25);
    assert_eq!(config.tokenizer_decoder_convs_strides, vec![1, 2, 2, 2]);
    assert_eq!(config.semantic_padded(), 128);
    assert_eq!(config.acoustic_padded(), 128);
    assert_eq!(config.audio_embedding_size(), 256);
    assert_eq!(config.num_codebooks(), 7);

    // The Mistral params.json layout: the nested blocks rename into the
    // flat fields, and missing blocks take the dataclass defaults.
    let params = serde_json::json!({
        "dim": 3072,
        "n_layers": 26,
        "multimodal": {
            "bos_token_id": 1,
            "audio_model_args": {
                "semantic_codebook_size": 8192,
                "acoustic_codebook_size": 21,
                "n_acoustic_codebook": 36,
                "audio_token_id": 24,
                "begin_audio_token_id": 25,
                "audio_encoding_args": {
                    "sampling_rate": 24000,
                    "frame_rate": 12.5,
                    "num_codebooks": 37
                },
                "acoustic_transformer_args": {
                    "dim": 3072,
                    "n_layers": 3,
                    "head_dim": 128,
                    "hidden_dim": 9216,
                    "n_heads": 32,
                    "n_kv_heads": 8,
                    "rope_theta": 10000.0,
                    "sigma": 1e-5,
                    "sigma_max": 1.0
                }
            },
            "audio_tokenizer_args": {
                "dim": 1024,
                "hidden_dim": 4096,
                "n_heads": 8,
                "n_kv_heads": 8,
                "head_dim": 128,
                "pretransform_patch_size": 240,
                "patch_proj_kernel_size": 7,
                "semantic_dim": 256,
                "acoustic_dim": 36,
                "norm_eps": 0.01,
                "decoder_transformer_lengths_str": "2,2,2,2",
                "decoder_convs_kernels_str": "3,4,4,4",
                "decoder_convs_strides_str": "1,2,2,2"
            }
        }
    });
    let resolved = super::ModelConfig::from_json(&params).expect("params format");
    assert_eq!(resolved.dim, 3072);
    assert_eq!(resolved.n_layers, 26);
    assert_eq!(resolved.head_dim, 128);
    assert_eq!(resolved.hidden_dim, 9216);
    assert_eq!(resolved.n_heads, 32);
    assert_eq!(resolved.n_kv_heads, 8);
    assert_eq!(resolved.vocab_size, 131072);
    assert!((resolved.rope_theta - 1_000_000.0).abs() < 1.0);
    assert_eq!(resolved.semantic_codebook_size, 8192);
    assert_eq!(resolved.acoustic_codebook_size, 21);
    assert_eq!(resolved.n_acoustic_codebook, 36);
    assert_eq!(resolved.sample_rate, 24000);
    assert_eq!(resolved.acoustic_n_layers, 3);
    assert_eq!(resolved.tokenizer_dim, 1024);
    assert_eq!(resolved.tokenizer_patch_size, 240);
    assert_eq!(resolved.tokenizer_decoder_convs_strides, vec![1, 2, 2, 2]);
    assert_eq!(resolved.semantic_padded(), 8320);
    assert_eq!(resolved.acoustic_padded(), 768);
    assert_eq!(resolved.audio_embedding_size(), 9088);
}

#[test]
fn generate_validates_inputs_and_voices() {
    let mut model = Model::open(&testdata("generate")).expect("family model loads");
    let mut noise = SeededFlowNoise::new(1);
    let error = model
        .generate(
            &[],
            Some("casual_male"),
            &GenerateParams::default(),
            &mut noise,
        )
        .expect_err("empty prompt");
    assert!(matches!(error, SpeechError::Input { .. }));
    let error = model
        .generate(
            &[4, 25],
            None,
            &GenerateParams { max_tokens: 0 },
            &mut noise,
        )
        .expect_err("zero max tokens");
    assert!(matches!(error, SpeechError::Input { .. }));
    let error = model
        .generate(
            &[4, 25],
            Some("no_such_voice"),
            &GenerateParams::default(),
            &mut noise,
        )
        .expect_err("unknown voice");
    assert!(matches!(error, SpeechError::Input { why } if why.contains("no_such_voice")));
    let voices = model.voices();
    assert_eq!(voices, vec!["casual_male"]);
}

#[test]
fn semantic_mask_leaves_only_the_special_and_live_range() {
    let traces = read_json(&testdata("generate/traces.json"));
    let model = Model::open(&testdata("generate")).expect("family model loads");
    // The masked argmax over the padded head: the Rust head exposes the
    // padded width; the fixture nominal (5) and end (1) codes sit inside
    // the kept range while index 0 and the padded tail are masked.
    let padded = model.config.semantic_padded();
    let keep = model.config.semantic_codebook_size + 2;
    assert!(keep < padded);
    assert!(5 < keep);
    // The head consumed the recorded hidden directly.
    let h = f32_vec(&traces["steps"][0]["hidden"]);
    assert_eq!(h.len(), model.config.dim);
    let semantic = model.acoustic.predict_semantic(&h);
    assert_eq!(
        semantic,
        traces["steps"][0]["semantic"].as_u64().unwrap() as usize
    );
}

#[test]
fn round_ties_even_matches_mx_round() {
    assert_eq!(super::round_ties_even(2.5), 2.0);
    assert_eq!(super::round_ties_even(3.5), 4.0);
    assert_eq!(super::round_ties_even(-2.5), -2.0);
    assert_eq!(super::round_ties_even(0.5), 0.0);
    assert_eq!(super::round_ties_even(1.4), 1.0);
    assert_eq!(super::round_ties_even(1.6), 2.0);
}

#[test]
fn alibi_slopes_follow_the_reference_formula() {
    // Four heads: start 2^-2, each slope start^i.
    let slopes = super::alibi_slopes(4);
    let want = [0.25f32, 0.0625, 0.015625, 0.00390625];
    assert_eq!(slopes.len(), 4);
    for (got, expected) in slopes.iter().zip(want) {
        assert!((got - expected).abs() < 1e-7, "{got} vs {expected}");
    }
    // Non-power head counts interleave the next power's slopes.
    let slopes = super::alibi_slopes(6);
    assert_eq!(slopes.len(), 6);
    let four = super::alibi_slopes(4);
    let eight = super::alibi_slopes(8);
    assert_eq!(slopes[0], four[0]);
    assert_eq!(slopes[4], eight[0]);
    assert_eq!(slopes[5], eight[2]);
}
